// exam-data.js — the final exams of the courses (exam.html, exam.js). 12 questions per course, EN + FR.
// A question is a multiple choice { q, o: [options], a: index of the right one, e: explanation }
// or a calculation { q, n: answer, tol: tolerance, u: unit, e: explanation }. Pass mark: 70 %.
// The courses "Code a robot arm in Python" and "Wheeled mobile robots, part 2" have their own exam in their last lesson.
window.RA_EXAMS = {
  learn: [
    { q: ['What makes a machine a robot?', 'Qu\'est-ce qui fait d\'une machine un robot ?'], o: [['It senses, decides and acts, and it can be reprogrammed', 'Elle perçoit, décide et agit, et on peut la reprogrammer'], ['It has an electric motor', 'Elle a un moteur électrique'], ['It is made of metal', 'Elle est en métal'], ['A person drives it with a joystick', 'Une personne la pilote avec un joystick']], a: 0, e: ['A robot measures, decides and acts again and again, and a new program gives it a new task.', 'Un robot mesure, décide et agit en boucle, et un nouveau programme lui donne une nouvelle tâche.'] },
    { q: ['A serial arm has 5 joints. How many links does it have, counting the base?', 'Un bras série a 5 liaisons. Combien a-t-il de corps, en comptant la base ?'], n: 6, tol: 0.01, u: '', e: ['n joints connect n + 1 links: 5 + 1 = 6.', 'n liaisons relient n + 1 corps : 5 + 1 = 6.'] },
    { q: ['How is a SCARA robot named by its joints, from the base?', 'Comment nomme-t-on un robot SCARA par ses liaisons, depuis la base ?'], o: [['R-R-P-R', 'R-R-P-R'], ['P-P-P', 'P-P-P'], ['R-R-R-R-R-R', 'R-R-R-R-R-R'], ['R-P-P', 'R-P-P']], a: 0, e: ['Two revolute joints in a plane, a prismatic joint going down, and a revolute joint for the tool.', 'Deux liaisons rotoïdes dans un plan, une liaison prismatique qui descend, et une rotoïde pour l\'outil.'] },
    { q: ['How many degrees of freedom does a free object have in space?', 'Combien de degrés de liberté a un objet libre dans l\'espace ?'], n: 6, tol: 0.01, u: '', e: ['3 positions (x, y, z) and 3 orientations.', '3 positions (x, y, z) et 3 orientations.'] },
    { q: ['What is the TCP?', 'Qu\'est-ce que le TCP ?'], o: [['The point of the tool that the robot places (tool centre point)', 'Le point de l\'outil que le robot place (point central de l\'outil)'], ['The motor of the last joint', 'Le moteur de la dernière liaison'], ['The cable that links the robot to the computer', 'Le câble qui relie le robot à l\'ordinateur'], ['The base of the robot', 'La base du robot']], a: 0, e: ['The TCP is, for example, the tip of a torch or the middle of the fingers of a gripper.', 'Le TCP est par exemple la pointe d\'une torche ou le milieu des doigts d\'une pince.'] },
    { q: ['2-link planar arm: L₁ = 0.5 m, L₂ = 0.3 m, θ₁ = 0°, θ₂ = 90°. What is the height y of the tool (m)?', 'Bras plan à 2 corps : L₁ = 0,5 m, L₂ = 0,3 m, θ₁ = 0°, θ₂ = 90°. Quelle est la hauteur y de l\'outil (m) ?'], n: 0.3, tol: 0.01, u: 'm', e: ['y = L₁ sin θ₁ + L₂ sin(θ₁ + θ₂) = 0 + 0.3 × sin 90° = 0.3 m.', 'y = L₁ sin θ₁ + L₂ sin(θ₁ + θ₂) = 0 + 0,3 × sin 90° = 0,3 m.'] },
    { q: ['For a reachable point inside the workspace, how many solutions does the inverse kinematics of a 2-link arm have?', 'Pour un point atteignable à l\'intérieur de l\'espace de travail, combien de solutions a la cinématique inverse d\'un bras à 2 corps ?'], o: [['2 (elbow up and elbow down)', '2 (coude en haut et coude en bas)'], ['Exactly 1', 'Exactement 1'], ['None', 'Aucune'], ['An infinity', 'Une infinité']], a: 0, e: ['The same point can be reached with the elbow on one side or the other.', 'Le même point peut être atteint avec le coude d\'un côté ou de l\'autre.'] },
    { q: ['A 2-link arm has L₁ = 0.6 m and L₂ = 0.4 m. What is the inner radius of its workspace (m)?', 'Un bras à 2 corps a L₁ = 0,6 m et L₂ = 0,4 m. Quel est le rayon intérieur de son espace de travail (m) ?'], n: 0.2, tol: 0.01, u: 'm', e: ['The workspace is a ring between |L₁ − L₂| = 0.2 m and L₁ + L₂ = 1 m.', 'L\'espace de travail est un anneau entre |L₁ − L₂| = 0,2 m et L₁ + L₂ = 1 m.'] },
    { q: ['A motor gives 2 N·m through a gearbox of ratio 50 (no losses). Output torque (N·m)?', 'Un moteur donne 2 N·m à travers un réducteur de rapport 50 (sans pertes). Couple de sortie (N·m) ?'], n: 100, tol: 0.5, u: 'N·m', e: ['A gearbox multiplies the torque by its ratio: 2 × 50 = 100 N·m (and divides the speed by 50).', 'Un réducteur multiplie le couple par son rapport : 2 × 50 = 100 N·m (et divise la vitesse par 50).'] },
    { q: ['What is the right order of a closed control loop?', 'Quel est le bon ordre d\'une boucle de commande fermée ?'], o: [['Measure → compare with the target → correct → measure again', 'Mesurer → comparer à la consigne → corriger → mesurer à nouveau'], ['Correct → stop → measure', 'Corriger → s\'arrêter → mesurer'], ['Send the command once and wait', 'Envoyer la commande une fois et attendre'], ['Measure only at the start', 'Mesurer seulement au départ']], a: 0, e: ['The loop repeats all the time, so the error is corrected as soon as it appears.', 'La boucle se répète en permanence, donc l\'erreur est corrigée dès qu\'elle apparaît.'] },
    { q: ['In a DH table, what is the variable of a prismatic joint?', 'Dans un tableau DH, quelle est la variable d\'une liaison prismatique ?'], o: [['d', 'd'], ['θ', 'θ'], ['a', 'a'], ['α', 'α']], a: 0, e: ['A prismatic joint slides along z: its offset d changes. For a revolute joint, θ changes.', 'Une liaison prismatique glisse le long de z : son décalage d change. Pour une rotoïde, c\'est θ.'] },
    { q: ['Convert 90° into radians.', 'Convertissez 90° en radians.'], n: Math.PI / 2, tol: 0.01, u: 'rad', e: ['rad = deg × π / 180 = 90 × π / 180 = π / 2 ≈ 1.571.', 'rad = deg × π / 180 = 90 × π / 180 = π / 2 ≈ 1,571.'] }
  ],
  mk: [
    { q: ['Convert 45° into radians.', 'Convertissez 45° en radians.'], n: Math.PI / 4, tol: 0.005, u: 'rad', e: ['45 × π / 180 = π / 4 ≈ 0.785.', '45 × π / 180 = π / 4 ≈ 0,785.'] },
    { q: ['An arm of length 2 m makes an angle of 30° with the x axis. Height y of its end (m)?', 'Un bras de 2 m fait un angle de 30° avec l\'axe x. Hauteur y de son extrémité (m) ?'], n: 1, tol: 0.01, u: 'm', e: ['y = L sin θ = 2 × sin 30° = 2 × 0.5 = 1 m.', 'y = L sin θ = 2 × sin 30° = 2 × 0,5 = 1 m.'] },
    { q: ['Why use atan2(y, x) instead of arctan(y / x)?', 'Pourquoi utiliser atan2(y, x) plutôt que arctan(y / x) ?'], o: [['atan2 gives the angle in the right quadrant, and works when x = 0', 'atan2 donne l\'angle dans le bon quadrant, et marche quand x = 0'], ['atan2 is faster', 'atan2 est plus rapide'], ['arctan only works in degrees', 'arctan ne marche qu\'en degrés'], ['They always give the same result', 'Elles donnent toujours le même résultat']], a: 0, e: ['arctan(y / x) cannot tell (1, 1) from (−1, −1), and divides by zero when x = 0.', 'arctan(y / x) ne distingue pas (1, 1) de (−1, −1), et divise par zéro quand x = 0.'] },
    { q: ['Length of the vector (3, 4, 12)?', 'Longueur du vecteur (3, 4, 12) ?'], n: 13, tol: 0.01, u: '', e: ['√(9 + 16 + 144) = √169 = 13.', '√(9 + 16 + 144) = √169 = 13.'] },
    { q: ['The dot product of two non-zero vectors is 0. What does it mean?', 'Le produit scalaire de deux vecteurs non nuls vaut 0. Qu\'est-ce que cela veut dire ?'], o: [['They are perpendicular', 'Ils sont perpendiculaires'], ['They are parallel', 'Ils sont parallèles'], ['They have the same length', 'Ils ont la même longueur'], ['One of them is a unit vector', 'L\'un d\'eux est unitaire']], a: 0, e: ['a · b = |a| |b| cos(angle) = 0 means cos = 0: the angle is 90°.', 'a · b = |a| |b| cos(angle) = 0 veut dire cos = 0 : l\'angle vaut 90°.'] },
    { q: ['Determinant of the matrix ( 2 3 ; 1 4 )?', 'Déterminant de la matrice ( 2 3 ; 1 4 ) ?'], n: 5, tol: 0.01, u: '', e: ['det = a d − b c = 2 × 4 − 3 × 1 = 5.', 'det = a d − b c = 2 × 4 − 3 × 1 = 5.'] },
    { q: ['What is the inverse of a rotation matrix R?', 'Quelle est l\'inverse d\'une matrice de rotation R ?'], o: [['Its transpose Rᵀ', 'Sa transposée Rᵀ'], ['−R', '−R'], ['R itself', 'R elle-même'], ['It has no inverse', 'Elle n\'a pas d\'inverse']], a: 0, e: ['A rotation is orthonormal: Rᵀ R = I, so R⁻¹ = Rᵀ.', 'Une rotation est orthonormée : Rᵀ R = I, donc R⁻¹ = Rᵀ.'] },
    { q: ['The product A B applied to a vector v means…', 'Le produit A B appliqué à un vecteur v veut dire…'], o: [['B is applied first, then A', 'B est appliquée d\'abord, puis A'], ['A is applied first, then B', 'A est appliquée d\'abord, puis B'], ['The order does not matter', 'L\'ordre n\'a pas d\'importance'], ['A and B are added', 'A et B sont additionnées']], a: 0, e: ['A B v = A (B v): B acts on v first. In general A B ≠ B A.', 'A B v = A (B v) : B agit d\'abord sur v. En général A B ≠ B A.'] },
    { q: ['In which order are the 4 parameters of a standard DH row applied?', 'Dans quel ordre s\'appliquent les 4 paramètres d\'une ligne DH standard ?'], o: [['θ, d (along z), then a, α (along x)', 'θ, d (selon z), puis a, α (selon x)'], ['α, a, then θ, d', 'α, a, puis θ, d'], ['a, d, θ, α', 'a, d, θ, α'], ['Any order', 'N\'importe quel ordre']], a: 0, e: ['Standard DH: θ and d along z, then a and α along x. Modified DH uses α, a, θ, d.', 'DH standard : θ et d selon z, puis a et α selon x. Le DH modifié utilise α, a, θ, d.'] },
    { q: ['y = 0.5 sin θ, with θ = 0 and θ̇ = 2 rad/s. Speed ẏ (m/s)?', 'y = 0,5 sin θ, avec θ = 0 et θ̇ = 2 rad/s. Vitesse ẏ (m/s) ?'], n: 1, tol: 0.01, u: 'm/s', e: ['Chain rule: ẏ = 0.5 cos θ · θ̇ = 0.5 × 1 × 2 = 1 m/s.', 'Dérivée d\'une composée : ẏ = 0,5 cos θ · θ̇ = 0,5 × 1 × 2 = 1 m/s.'] },
    { q: ['A sensor has σ = 2 cm. You average 4 independent measurements. σ of the mean (cm)?', 'Un capteur a σ = 2 cm. Vous moyennez 4 mesures indépendantes. σ de la moyenne (cm) ?'], n: 1, tol: 0.01, u: 'cm', e: ['Averaging N measurements divides σ by √N: 2 / √4 = 1 cm.', 'Moyenner N mesures divise σ par √N : 2 / √4 = 1 cm.'] },
    { q: ['Which quaternion describes a rotation of angle θ around the unit axis u?', 'Quel quaternion décrit une rotation d\'angle θ autour de l\'axe unitaire u ?'], o: [['(cos θ/2, u sin θ/2)', '(cos θ/2, u sin θ/2)'], ['(cos θ, u sin θ)', '(cos θ, u sin θ)'], ['(θ, u)', '(θ, u)'], ['(sin θ/2, u cos θ/2)', '(sin θ/2, u cos θ/2)']], a: 0, e: ['The half angle appears: q = (cos θ/2, u sin θ/2), a unit quaternion.', 'C\'est le demi-angle qui apparaît : q = (cos θ/2, u sin θ/2), un quaternion unitaire.'] }
  ],
  maths: [
    { q: ['One revolute joint with a link L = 0.4 m at θ = 60°. Position x of the tip (m)?', 'Une liaison rotoïde avec un corps L = 0,4 m à θ = 60°. Position x de l\'extrémité (m) ?'], n: 0.2, tol: 0.005, u: 'm', e: ['x = L cos θ = 0.4 × 0.5 = 0.2 m.', 'x = L cos θ = 0,4 × 0,5 = 0,2 m.'] },
    { q: ['A link of 0.5 m turns at ω = 2 rad/s. Speed of its tip (m/s)?', 'Un corps de 0,5 m tourne à ω = 2 rad/s. Vitesse de son extrémité (m/s) ?'], n: 1, tol: 0.01, u: 'm/s', e: ['v = L ω = 0.5 × 2 = 1 m/s.', 'v = L ω = 0,5 × 2 = 1 m/s.'] },
    { q: ['Angle of the point (1, 1), in degrees?', 'Angle du point (1, 1), en degrés ?'], n: 45, tol: 0.1, u: '°', e: ['atan2(1, 1) = 45°.', 'atan2(1, 1) = 45°.'] },
    { q: ['2-axis arm, L₁ = L₂ = 1 m, θ₁ = 90°, θ₂ = −90°. Position x of the tool (m)?', 'Bras 2 axes, L₁ = L₂ = 1 m, θ₁ = 90°, θ₂ = −90°. Position x de l\'outil (m) ?'], n: 1, tol: 0.01, u: 'm', e: ['x = cos 90° + cos(90° − 90°) = 0 + 1 = 1 m (and y = 1 m).', 'x = cos 90° + cos(90° − 90°) = 0 + 1 = 1 m (et y = 1 m).'] },
    { q: ['2-axis arm with L₁ = L₂ = 1 m reaching (1, 1). |θ₂| in degrees?', 'Bras 2 axes avec L₁ = L₂ = 1 m qui atteint (1, 1). |θ₂| en degrés ?'], n: 90, tol: 0.5, u: '°', e: ['cos θ₂ = (x² + y² − L₁² − L₂²) / (2 L₁ L₂) = (2 − 2) / 2 = 0, so |θ₂| = 90°.', 'cos θ₂ = (x² + y² − L₁² − L₂²) / (2 L₁ L₂) = (2 − 2) / 2 = 0, donc |θ₂| = 90°.'] },
    { q: ['What is the workspace of a 2-axis planar arm without joint limits?', 'Quel est l\'espace de travail d\'un bras plan 2 axes sans butées ?'], o: [['A ring between |L₁ − L₂| and L₁ + L₂', 'Un anneau entre |L₁ − L₂| et L₁ + L₂'], ['A full disc of radius L₁', 'Un disque plein de rayon L₁'], ['A square of side L₁ + L₂', 'Un carré de côté L₁ + L₂'], ['A straight line', 'Une ligne droite']], a: 0, e: ['The tool cannot go further than L₁ + L₂ nor closer than |L₁ − L₂|.', 'L\'outil ne peut pas aller plus loin que L₁ + L₂ ni plus près que |L₁ − L₂|.'] },
    { q: ['How are two frame changes chained?', 'Comment enchaîne-t-on deux changements de repère ?'], o: [['By multiplying the matrices: T₀₂ = T₀₁ × T₁₂', 'En multipliant les matrices : T₀₂ = T₀₁ × T₁₂'], ['By adding the matrices', 'En additionnant les matrices'], ['By taking the larger one', 'En prenant la plus grande'], ['By inverting both', 'En inversant les deux']], a: 0, e: ['Each homogeneous matrix moves from one frame to the next: they multiply in order.', 'Chaque matrice homogène passe d\'un repère au suivant : elles se multiplient dans l\'ordre.'] },
    { q: ['For a planar arm, which DH parameters are always 0?', 'Pour un bras plan, quels paramètres DH valent toujours 0 ?'], o: [['d and α', 'd et α'], ['θ and a', 'θ et a'], ['a and α', 'a et α'], ['θ and d', 'θ et d']], a: 0, e: ['All the joint axes are parallel and in the same plane: no offset d, no twist α.', 'Tous les axes sont parallèles et dans le même plan : ni décalage d, ni torsion α.'] },
    { q: ['Trapezoid: 1 s of acceleration to 0.5 m/s, 2 s at 0.5 m/s, 1 s of braking. Distance (m)?', 'Trapèze : 1 s d\'accélération jusqu\'à 0,5 m/s, 2 s à 0,5 m/s, 1 s de freinage. Distance (m) ?'], n: 1.5, tol: 0.01, u: 'm', e: ['Area under the speed: 0.25 + 1 + 0.25 = 1.5 m.', 'Aire sous la vitesse : 0,25 + 1 + 0,25 = 1,5 m.'] },
    { q: ['Several motors move together. How do they all arrive at the same time?', 'Plusieurs moteurs bougent ensemble. Comment arrivent-ils tous en même temps ?'], o: [['The fast ones are slowed down to the time of the slowest', 'On ralentit les rapides au temps du plus lent'], ['Each one goes at full speed', 'Chacun va à pleine vitesse'], ['The slowest one is skipped', 'On saute le plus lent'], ['They move one after the other', 'Ils bougent l\'un après l\'autre']], a: 0, e: ['Synchronised motion: every joint uses the duration of the longest move.', 'Mouvement synchronisé : chaque liaison prend la durée du mouvement le plus long.'] },
    { q: ['What are the joint space and the task space?', 'Que sont l\'espace articulaire et l\'espace opérationnel ?'], o: [['The joint values (angles) / where the tool is', 'Les valeurs des liaisons (angles) / là où est l\'outil'], ['The room / the factory', 'La pièce / l\'usine'], ['The motors / the sensors', 'Les moteurs / les capteurs'], ['Two names of the same thing', 'Deux noms de la même chose']], a: 0, e: ['The direct model goes from the joint space to the task space, the inverse model back.', 'Le modèle direct va de l\'espace articulaire à l\'espace opérationnel, le modèle inverse revient.'] },
    { q: ['The rotation of 90° is applied to the vector (1, 0). Component y of the result?', 'On applique la rotation de 90° au vecteur (1, 0). Composante y du résultat ?'], n: 1, tol: 0.01, u: '', e: ['R(90°) (1, 0) = (cos 90°, sin 90°) = (0, 1).', 'R(90°) (1, 0) = (cos 90°, sin 90°) = (0, 1).'] }
  ],
  model: [
    { q: ['What is true for every rotation matrix R?', 'Qu\'est-ce qui est vrai pour toute matrice de rotation R ?'], o: [['Rᵀ R = I and det R = +1', 'Rᵀ R = I et det R = +1'], ['R is symmetric', 'R est symétrique'], ['det R = 0', 'det R = 0'], ['Its columns add up to 1', 'Ses colonnes ont une somme de 1']], a: 0, e: ['Its columns are orthonormal axes: R is orthonormal, and +1 means no mirror.', 'Ses colonnes sont des axes orthonormés : R est orthonormée, et +1 veut dire pas de miroir.'] },
    { q: ['What is gimbal lock?', 'Qu\'est-ce que le blocage de cardan ?'], o: [['Two rotation axes line up and one angle of the description is lost', 'Deux axes de rotation s\'alignent et un angle de la description est perdu'], ['A motor brake', 'Un frein de moteur'], ['A joint limit', 'Une butée articulaire'], ['A broken gearbox', 'Un réducteur cassé']], a: 0, e: ['It is a singularity of the 3-angle description, not of the object.', 'C\'est une singularité de la description à 3 angles, pas de l\'objet.'] },
    { q: ['How is a point written to be multiplied by a 4 × 4 homogeneous matrix?', 'Comment écrit-on un point pour le multiplier par une matrice homogène 4 × 4 ?'], o: [['(x, y, z, 1)', '(x, y, z, 1)'], ['(x, y, z, 0)', '(x, y, z, 0)'], ['(1, x, y, z)', '(1, x, y, z)'], ['(x, y, z)', '(x, y, z)']], a: 0, e: ['The 1 lets the translation act on the point (a vector uses 0).', 'Le 1 permet à la translation d\'agir sur le point (un vecteur utilise 0).'] },
    { q: ['What is the inverse of T = ( R p ; 0 1 )?', 'Quelle est l\'inverse de T = ( R p ; 0 1 ) ?'], o: [['( Rᵀ −Rᵀp ; 0 1 )', '( Rᵀ −Rᵀp ; 0 1 )'], ['( −R −p ; 0 1 )', '( −R −p ; 0 1 )'], ['( Rᵀ p ; 0 1 )', '( Rᵀ p ; 0 1 )'], ['( R −p ; 0 1 )', '( R −p ; 0 1 )']], a: 0, e: ['Undo the rotation with Rᵀ, then the translation expressed in the new frame: −Rᵀ p.', 'On défait la rotation avec Rᵀ, puis la translation exprimée dans le nouveau repère : −Rᵀ p.'] },
    { q: ['In the modified DH convention (Khalil–Kleinfinger), where is frame i?', 'Dans la convention DH modifiée (Khalil–Kleinfinger), où est le repère i ?'], o: [['On the axis of joint i', 'Sur l\'axe de la liaison i'], ['At the far end of link i', 'Au bout du corps i'], ['At the tool', 'À l\'outil'], ['At the base for every i', 'À la base pour tout i']], a: 0, e: ['DHm: z_i is the axis of joint i, at the start of link i.', 'DHm : z_i est l\'axe de la liaison i, au début du corps i.'] },
    { q: ['In DHm, what is the variable of a prismatic joint (σ = 1)?', 'En DHm, quelle est la variable d\'une liaison prismatique (σ = 1) ?'], o: [['r', 'r'], ['θ', 'θ'], ['α', 'α'], ['d', 'd']], a: 0, e: ['r is the distance along z_i; θ is the variable of a revolute joint.', 'r est la distance selon z_i ; θ est la variable d\'une rotoïde.'] },
    { q: ['Which statement is right?', 'Quelle affirmation est juste ?'], o: [['The MGD always has one result; the MGI may have none, several or an infinity', 'Le MGD a toujours un résultat ; le MGI peut n\'en avoir aucun, plusieurs ou une infinité'], ['The MGI always has exactly one result', 'Le MGI a toujours exactement un résultat'], ['The MGD may have no result', 'Le MGD peut n\'avoir aucun résultat'], ['Both always have two results', 'Les deux ont toujours deux résultats']], a: 0, e: ['From the joints the pose is unique; from a pose there can be 0, a finite number or infinitely many joint sets.', 'À partir des liaisons la pose est unique ; à partir d\'une pose il peut y avoir 0, un nombre fini ou une infinité de solutions.'] },
    { q: ['Up to how many MGI solutions can a 6-axis robot with a spherical wrist have?', 'Jusqu\'à combien de solutions du MGI un robot 6 axes à poignet sphérique peut-il avoir ?'], n: 8, tol: 0.01, u: '', e: ['2 (shoulder) × 2 (elbow) × 2 (wrist flip) = 8.', '2 (épaule) × 2 (coude) × 2 (retournement du poignet) = 8.'] },
    { q: ['What is column i of the Jacobian J?', 'Qu\'est-ce que la colonne i de la jacobienne J ?'], o: [['The tool speed when only joint i moves at 1 rad/s', 'La vitesse de l\'outil quand seule la liaison i bouge à 1 rad/s'], ['The torque of motor i', 'Le couple du moteur i'], ['The position of joint i', 'La position de la liaison i'], ['The mass of link i', 'La masse du corps i']], a: 0, e: ['Ẋ = J q̇: each column is the effect of one joint speed on the tool.', 'Ẋ = J q̇ : chaque colonne est l\'effet d\'une vitesse articulaire sur l\'outil.'] },
    { q: ['Degree 5 motion law s(u) = 10u³ − 15u⁴ + 6u⁵. Value of s at half time (u = 0.5)?', 'Loi de degré 5 s(u) = 10u³ − 15u⁴ + 6u⁵. Valeur de s à mi-parcours (u = 0,5) ?'], n: 0.5, tol: 0.005, u: '', e: ['10 × 0.125 − 15 × 0.0625 + 6 × 0.03125 = 1.25 − 0.9375 + 0.1875 = 0.5.', '10 × 0,125 − 15 × 0,0625 + 6 × 0,03125 = 1,25 − 0,9375 + 0,1875 = 0,5.'] },
    { q: ['In τ = M(q) q̈ + C(q, q̇) q̇ + G(q), what is G(q)?', 'Dans τ = M(q) q̈ + C(q, q̇) q̇ + G(q), qu\'est-ce que G(q) ?'], o: [['The torque needed to hold the arm against gravity', 'Le couple nécessaire pour tenir le bras contre la gravité'], ['The inertia of the arm', 'L\'inertie du bras'], ['The friction', 'Le frottement'], ['The speed of the tool', 'La vitesse de l\'outil']], a: 0, e: ['G(q) depends only on the posture; it is the base of gravity compensation.', 'G(q) ne dépend que de la posture ; c\'est la base de la compensation de gravité.'] },
    { q: ['One link of 0.5 m at θ = 0 turns at θ̇ = 2 rad/s. Vertical speed of its tip (m/s)?', 'Un corps de 0,5 m à θ = 0 tourne à θ̇ = 2 rad/s. Vitesse verticale de son extrémité (m/s) ?'], n: 1, tol: 0.01, u: 'm/s', e: ['ẏ = L cos θ · θ̇ = 0.5 × 1 × 2 = 1 m/s: the Jacobian of one link.', 'ẏ = L cos θ · θ̇ = 0,5 × 1 × 2 = 1 m/s : la jacobienne d\'un corps.'] }
  ],
  sing: [
    { q: ['What is a singularity of a robot?', 'Qu\'est-ce qu\'une singularité d\'un robot ?'], o: [['A posture where the Jacobian loses rank: one tool direction is lost', 'Une posture où la jacobienne perd du rang : une direction de l\'outil est perdue'], ['A collision', 'Une collision'], ['A broken motor', 'Un moteur en panne'], ['The fastest posture', 'La posture la plus rapide']], a: 0, e: ['For a square J: det J = 0. No joint speed can move the tool in some direction.', 'Pour une J carrée : det J = 0. Aucune vitesse articulaire ne peut bouger l\'outil dans une direction.'] },
    { q: ['2-link arm, L₁ = 1 m, L₂ = 0.5 m, θ₂ = 90°. det J = L₁ L₂ sin θ₂ = ?', 'Bras 2 corps, L₁ = 1 m, L₂ = 0,5 m, θ₂ = 90°. det J = L₁ L₂ sin θ₂ = ?'], n: 0.5, tol: 0.005, u: '', e: ['1 × 0.5 × sin 90° = 0.5: far from a singularity (θ₂ = 0° or 180°).', '1 × 0,5 × sin 90° = 0,5 : loin d\'une singularité (θ₂ = 0° ou 180°).'] },
    { q: ['When is a 2-link arm at an elbow singularity?', 'Quand un bras à 2 corps est-il en singularité de coude ?'], o: [['When the arm is fully stretched or folded (θ₂ = 0° or 180°)', 'Quand le bras est tendu ou replié (θ₂ = 0° ou 180°)'], ['When θ₁ = 90°', 'Quand θ₁ = 90°'], ['When it moves fast', 'Quand il bouge vite'], ['Never', 'Jamais']], a: 0, e: ['det J = L₁ L₂ sin θ₂ = 0 when θ₂ = 0° or 180°.', 'det J = L₁ L₂ sin θ₂ = 0 quand θ₂ = 0° ou 180°.'] },
    { q: ['What is the wrist singularity of a 6-axis robot?', 'Qu\'est-ce que la singularité de poignet d\'un robot 6 axes ?'], o: [['θ₅ = 0: axes 4 and 6 are aligned', 'θ₅ = 0 : les axes 4 et 6 sont alignés'], ['θ₁ = 0', 'θ₁ = 0'], ['The gripper is closed', 'La pince est fermée'], ['The arm is at full speed', 'Le bras est à pleine vitesse']], a: 0, e: ['With axes 4 and 6 aligned, turning one or the other gives the same motion: one direction is lost.', 'Avec les axes 4 et 6 alignés, tourner l\'un ou l\'autre donne le même mouvement : une direction est perdue.'] },
    { q: ['Singular values of J: σmax = 4, σmin = 0.5. Condition number κ?', 'Valeurs singulières de J : σmax = 4, σmin = 0,5. Conditionnement κ ?'], n: 8, tol: 0.01, u: '', e: ['κ = σmax / σmin = 4 / 0.5 = 8 (1 is perfect, very large is dangerous).', 'κ = σmax / σmin = 4 / 0,5 = 8 (1 est parfait, très grand est dangereux).'] },
    { q: ['What happens to the joint speeds near a singularity, for a normal tool speed?', 'Que deviennent les vitesses articulaires près d\'une singularité, pour une vitesse d\'outil normale ?'], o: [['They become huge', 'Elles deviennent énormes'], ['They become zero', 'Elles deviennent nulles'], ['They do not change', 'Elles ne changent pas'], ['They change sign at random', 'Elles changent de signe au hasard']], a: 0, e: ['q̇ = J⁻¹ Ẋ and J⁻¹ blows up when det J → 0.', 'q̇ = J⁻¹ Ẋ et J⁻¹ explose quand det J → 0.'] },
    { q: ['τ = Jᵀ F. What happens to a force applied in a singular direction?', 'τ = Jᵀ F. Que se passe-t-il pour une force appliquée dans une direction singulière ?'], o: [['The robot holds it with almost no motor torque', 'Le robot la tient avec presque aucun couple moteur'], ['The motors must give infinite torque', 'Les moteurs doivent donner un couple infini'], ['The robot falls', 'Le robot tombe'], ['Nothing special', 'Rien de spécial']], a: 0, e: ['In that direction the structure itself carries the load, like a stretched arm holding a suitcase.', 'Dans cette direction, la structure porte elle-même la charge, comme un bras tendu qui tient une valise.'] },
    { q: ['How do quaternions help with gimbal lock?', 'Comment les quaternions aident-ils face au blocage de cardan ?'], o: [['They describe every orientation without any lost angle', 'Ils décrivent toutes les orientations sans angle perdu'], ['They make the robot faster', 'Ils rendent le robot plus rapide'], ['They remove the joint limits', 'Ils suppriment les butées'], ['They do not help', 'Ils n\'aident pas']], a: 0, e: ['Gimbal lock is a problem of the 3-angle description; 4 numbers avoid it.', 'Le blocage de cardan est un problème de la description à 3 angles ; 4 nombres l\'évitent.'] },
    { q: ['A 7-joint arm does a 6-DOF task. How many degrees of redundancy does it have?', 'Un bras à 7 liaisons fait une tâche à 6 DDL. Combien de degrés de redondance a-t-il ?'], n: 1, tol: 0.01, u: '', e: ['n − m = 7 − 6 = 1: one motion of the joints keeps the tool still (the null space).', 'n − m = 7 − 6 = 1 : un mouvement des liaisons garde l\'outil immobile (le noyau).'] },
    { q: ['What does the damped least squares q̇ = Jᵀ (J Jᵀ + λ² I)⁻¹ Ẋ do?', 'Que fait la méthode des moindres carrés amortis q̇ = Jᵀ (J Jᵀ + λ² I)⁻¹ Ẋ ?'], o: [['It keeps the joint speeds bounded near singularities', 'Elle garde les vitesses articulaires bornées près des singularités'], ['It removes the singularities from the robot', 'Elle supprime les singularités du robot'], ['It makes the tool go faster', 'Elle fait aller l\'outil plus vite'], ['It computes the dynamics', 'Elle calcule la dynamique']], a: 0, e: ['λ trades a small tracking error for bounded joint speeds.', 'λ échange une petite erreur de suivi contre des vitesses articulaires bornées.'] },
    { q: ['A large manipulability w = √det(J Jᵀ) means…', 'Une grande manipulabilité w = √det(J Jᵀ) veut dire…'], o: [['The posture is far from a singularity', 'La posture est loin d\'une singularité'], ['The robot is singular', 'Le robot est singulier'], ['The robot is heavy', 'Le robot est lourd'], ['The joints are at their limits', 'Les liaisons sont en butée']], a: 0, e: ['w = 0 at a singularity; good postures have a large w.', 'w = 0 en singularité ; les bonnes postures ont un grand w.'] },
    { q: ['2-link arm with L₁ = L₂ = 1 m and θ₂ = 30°. det J = L₁ L₂ sin θ₂ = ?', 'Bras 2 corps avec L₁ = L₂ = 1 m et θ₂ = 30°. det J = L₁ L₂ sin θ₂ = ?'], n: 0.5, tol: 0.005, u: '', e: ['1 × 1 × sin 30° = 0.5.', '1 × 1 × sin 30° = 0,5.'] }
  ],
  ctrl: [
    { q: ['A 2 kg mass at 0.5 m, arm horizontal. Holding torque (N·m)?', 'Une masse de 2 kg à 0,5 m, bras horizontal. Couple de maintien (N·m) ?'], n: 9.81, tol: 0.05, u: 'N·m', e: ['τ = m g l = 2 × 9.81 × 0.5 = 9.81 N·m: the gravity term.', 'τ = m g l = 2 × 9,81 × 0,5 = 9,81 N·m : le terme de gravité.'] },
    { q: ['Motor 0.5 N·m, gearbox ratio 100, efficiency 0.8. Output torque (N·m)?', 'Moteur 0,5 N·m, réducteur de rapport 100, rendement 0,8. Couple de sortie (N·m) ?'], n: 40, tol: 0.2, u: 'N·m', e: ['0.5 × 100 × 0.8 = 40 N·m.', '0,5 × 100 × 0,8 = 40 N·m.'] },
    { q: ['Resolution of a 12-bit absolute encoder, in degrees?', 'Résolution d\'un codeur absolu 12 bits, en degrés ?'], n: 360 / 4096, tol: 0.001, u: '°', e: ['2¹² = 4096 steps per turn: 360 / 4096 ≈ 0.088°.', '2¹² = 4096 pas par tour : 360 / 4096 ≈ 0,088°.'] },
    { q: ['Which term of a PID removes the error that remains?', 'Quel terme d\'un PID supprime l\'erreur qui reste ?'], o: [['I (integral)', 'I (intégral)'], ['P (proportional)', 'P (proportionnel)'], ['D (derivative)', 'D (dérivé)'], ['None of them', 'Aucun']], a: 0, e: ['The integral keeps growing while an error remains, until it is removed.', 'L\'intégrale grandit tant qu\'une erreur reste, jusqu\'à la supprimer.'] },
    { q: ['What happens with too much proportional gain?', 'Que se passe-t-il avec un gain proportionnel trop grand ?'], o: [['Overshoot and oscillations', 'Dépassement et oscillations'], ['The motor stops', 'Le moteur s\'arrête'], ['The response gets very slow', 'La réponse devient très lente'], ['Nothing', 'Rien']], a: 0, e: ['Too much gain → oscillations; too little → slow.', 'Trop de gain → oscillations ; trop peu → lenteur.'] },
    { q: ['What does gravity compensation add to the PID?', 'Qu\'ajoute la compensation de gravité au PID ?'], o: [['The computed gravity torque G(q)', 'Le couple de gravité calculé G(q)'], ['A larger integral gain', 'Un gain intégral plus grand'], ['A brake', 'Un frein'], ['A second motor', 'Un second moteur']], a: 0, e: ['The PID then only fights small errors.', 'Le PID ne combat alors que de petites erreurs.'] },
    { q: ['How does a robot behave under impedance control F = K (x_d − x) − B ẋ?', 'Comment se comporte un robot en commande d\'impédance F = K (x_d − x) − B ẋ ?'], o: [['Like a spring and a damper', 'Comme un ressort et un amortisseur'], ['Like a rigid wall', 'Comme un mur rigide'], ['Like a free mass', 'Comme une masse libre'], ['It follows positions only', 'Il ne suit que des positions']], a: 0, e: ['It yields to contact forces, which allows polishing, assembly and hand guiding.', 'Il cède aux efforts de contact, ce qui permet le polissage, l\'assemblage et le guidage à la main.'] },
    { q: ['In a PTP move, what does the tool path look like?', 'Dans un mouvement PTP, à quoi ressemble la trajectoire de l\'outil ?'], o: [['A curve: each joint moves on its own', 'Une courbe : chaque liaison bouge de son côté'], ['Always a straight line', 'Toujours une droite'], ['A circle', 'Un cercle'], ['The tool does not move', 'L\'outil ne bouge pas']], a: 0, e: ['For a straight line, use LIN (inverse kinematics at every point).', 'Pour une droite, on utilise LIN (cinématique inverse à chaque point).'] },
    { q: ['Which loop of the control stack is the fastest?', 'Quelle boucle de la chaîne de commande est la plus rapide ?'], o: [['The current loop', 'La boucle de courant'], ['The position loop', 'La boucle de position'], ['The trajectory planner', 'Le planificateur de trajectoire'], ['The program', 'Le programme']], a: 0, e: ['Typically: current 16–32 kHz, speed 4–8 kHz, position 1–2 kHz.', 'Typiquement : courant 16–32 kHz, vitesse 4–8 kHz, position 1–2 kHz.'] },
    { q: ['First-order system with τ = 0.2 s. After how long does a step response reach 95 % (s)?', 'Système du premier ordre avec τ = 0,2 s. Au bout de combien de temps la réponse à un échelon atteint-elle 95 % (s) ?'], n: 0.6, tol: 0.01, u: 's', e: ['95 % after 3τ = 0.6 s (63 % after τ).', '95 % après 3τ = 0,6 s (63 % après τ).'] },
    { q: ['P control of a first order with K = 1 and Kp = 4. Final error for a unit step?', 'Commande P d\'un premier ordre avec K = 1 et Kp = 4. Erreur finale pour un échelon unité ?'], n: 0.2, tol: 0.005, u: '', e: ['1 / (1 + K Kp) = 1 / 5 = 0.2.', '1 / (1 + K Kp) = 1 / 5 = 0,2.'] },
    { q: ['A delay of 10 ms at the crossover ω = 10 rad/s. Phase margin lost (degrees)?', 'Un retard de 10 ms à la pulsation de coupure ω = 10 rad/s. Marge de phase perdue (degrés) ?'], n: 0.1 * 180 / Math.PI, tol: 0.1, u: '°', e: ['ω T = 10 × 0.01 = 0.1 rad ≈ 5.7°.', 'ω T = 10 × 0,01 = 0,1 rad ≈ 5,7°.'] }
  ],
  ai: [
    { q: ['Which sensors are proprioceptive?', 'Quels capteurs sont proprioceptifs ?'], o: [['Encoders and IMU (they measure the robot itself)', 'Codeurs et centrale inertielle (ils mesurent le robot lui-même)'], ['Camera and lidar', 'Caméra et lidar'], ['Ultrasound and radar', 'Ultrasons et radar'], ['GPS only', 'Le GPS seulement']], a: 0, e: ['Exteroceptive sensors (camera, lidar, ultrasound) measure the world.', 'Les capteurs extéroceptifs (caméra, lidar, ultrasons) mesurent le monde.'] },
    { q: ['Ultrasound at c = 343 m/s, echo after 10 ms. Distance (m)?', 'Ultrasons à c = 343 m/s, écho après 10 ms. Distance (m) ?'], n: 1.715, tol: 0.01, u: 'm', e: ['d = c t / 2 = 343 × 0.01 / 2 ≈ 1.72 m (the sound goes and comes back).', 'd = c t / 2 = 343 × 0,01 / 2 ≈ 1,72 m (le son fait l\'aller et le retour).'] },
    { q: ['Pinhole camera, f = 800 px, point at X = 0.5 m, Z = 2 m. Image coordinate u from the centre (px)?', 'Caméra sténopé, f = 800 px, point à X = 0,5 m, Z = 2 m. Coordonnée image u depuis le centre (px) ?'], n: 200, tol: 1, u: 'px', e: ['u = f X / Z = 800 × 0.5 / 2 = 200 px.', 'u = f X / Z = 800 × 0,5 / 2 = 200 px.'] },
    { q: ['Stereo: f = 700 px, baseline B = 0.1 m, disparity d = 35 px. Depth Z (m)?', 'Stéréo : f = 700 px, base B = 0,1 m, disparité d = 35 px. Profondeur Z (m) ?'], n: 2, tol: 0.01, u: 'm', e: ['Z = f B / d = 700 × 0.1 / 35 = 2 m.', 'Z = f B / d = 700 × 0,1 / 35 = 2 m.'] },
    { q: ['Two measurements 10 and 12, both with σ = 1. Fused estimate?', 'Deux mesures 10 et 12, toutes deux avec σ = 1. Estimation fusionnée ?'], n: 11, tol: 0.01, u: '', e: ['Same weights 1/σ²: the mean, 11.', 'Mêmes poids 1/σ² : la moyenne, 11.'] },
    { q: ['Two estimates with σ₁ = σ₂ = 2. σ of the fused estimate?', 'Deux estimations avec σ₁ = σ₂ = 2. σ de l\'estimation fusionnée ?'], n: Math.SQRT2, tol: 0.01, u: '', e: ['1/σ² = 1/4 + 1/4 = 1/2, so σ = √2 ≈ 1.41: smaller than each one.', '1/σ² = 1/4 + 1/4 = 1/2, donc σ = √2 ≈ 1,41 : plus petit que chacune.'] },
    { q: ['How does the odometry error behave?', 'Comment se comporte l\'erreur d\'odométrie ?'], o: [['It grows with the distance travelled (drift)', 'Elle grandit avec la distance parcourue (dérive)'], ['It stays constant', 'Elle reste constante'], ['It decreases over time', 'Elle diminue avec le temps'], ['It is zero on a flat floor', 'Elle est nulle sur un sol plat']], a: 0, e: ['Each small error is added to the next: it must be corrected with landmarks.', 'Chaque petite erreur s\'ajoute à la suivante : il faut la corriger avec des repères.'] },
    { q: ['What does a loop closure do in SLAM?', 'Que fait une fermeture de boucle en SLAM ?'], o: [['It recognises a known place and removes the accumulated error', 'Elle reconnaît un lieu connu et supprime l\'erreur accumulée'], ['It closes a door', 'Elle ferme une porte'], ['It stops the robot', 'Elle arrête le robot'], ['It deletes the map', 'Elle efface la carte']], a: 0, e: ['Seeing the start again links the end of the path to its beginning and corrects the whole map.', 'Revoir le départ relie la fin du chemin à son début et corrige toute la carte.'] },
    { q: ['When does A* find the shortest path?', 'Quand A* trouve-t-il le plus court chemin ?'], o: [['When the guess h never overestimates the real cost', 'Quand l\'estimation h ne surestime jamais le vrai coût'], ['Always, whatever h', 'Toujours, quel que soit h'], ['Only on a grid of 10 × 10', 'Seulement sur une grille 10 × 10'], ['Never', 'Jamais']], a: 0, e: ['An admissible h (for example the straight-line distance) keeps A* optimal and fast.', 'Un h admissible (par exemple la distance à vol d\'oiseau) garde A* optimal et rapide.'] },
    { q: ['Why use RRT rather than a grid to plan a 6-axis arm?', 'Pourquoi utiliser RRT plutôt qu\'une grille pour planifier un bras 6 axes ?'], o: [['A 6-dimensional grid would be far too big', 'Une grille à 6 dimensions serait beaucoup trop grande'], ['RRT always finds the shortest path', 'RRT trouve toujours le plus court chemin'], ['Grids do not work for arms', 'Les grilles ne marchent pas pour les bras'], ['RRT does not need a collision check', 'RRT n\'a pas besoin de test de collision']], a: 0, e: ['Random sampling explores large configuration spaces; the path is then smoothed.', 'L\'échantillonnage aléatoire explore les grands espaces de configuration ; le chemin est ensuite lissé.'] },
    { q: ['In a behaviour tree, when does a Sequence fail?', 'Dans un arbre de comportement, quand une Séquence échoue-t-elle ?'], o: [['As soon as one of its children fails', 'Dès qu\'un de ses enfants échoue'], ['Only if all its children fail', 'Seulement si tous ses enfants échouent'], ['Never', 'Jamais'], ['After a fixed time', 'Après un temps fixe']], a: 0, e: ['A Sequence runs its children in order; a Fallback tries them until one succeeds.', 'Une Séquence exécute ses enfants dans l\'ordre ; un Fallback les essaie jusqu\'à ce que l\'un réussisse.'] },
    { q: ['How must a learned model be tested?', 'Comment doit-on tester un modèle appris ?'], o: [['On data it has never seen (test set)', 'Sur des données qu\'il n\'a jamais vues (jeu de test)'], ['On its training data', 'Sur ses données d\'entraînement'], ['It does not need tests', 'Il n\'a pas besoin de tests'], ['Only in simulation', 'Seulement en simulation']], a: 0, e: ['Otherwise you only measure how well it remembers.', 'Sinon on mesure seulement sa mémoire.'] }
  ],
  world: [
    { q: ['Which robot family is the fastest for picking light parts on a conveyor?', 'Quelle famille de robots est la plus rapide pour prendre des pièces légères sur un convoyeur ?'], o: [['Delta', 'Delta'], ['6-axis arm', 'Bras 6 axes'], ['Gantry', 'Portique'], ['Humanoid', 'Humanoïde']], a: 0, e: ['A Delta has its motors on the base and very light arms.', 'Un Delta a ses moteurs sur la base et des bras très légers.'] },
    { q: ['A 5 kg load at 0.8 m from the shoulder, arm horizontal. Torque (N·m)?', 'Une charge de 5 kg à 0,8 m de l\'épaule, bras horizontal. Couple (N·m) ?'], n: 5 * 9.81 * 0.8, tol: 0.1, u: 'N·m', e: ['τ = m g d = 5 × 9.81 × 0.8 ≈ 39.2 N·m: it grows with the reach.', 'τ = m g d = 5 × 9,81 × 0,8 ≈ 39,2 N·m : il grandit avec la portée.'] },
    { q: ['Suction cup of 40 mm diameter, pressure difference 60 kPa. Holding force (N)?', 'Ventouse de 40 mm de diamètre, différence de pression 60 kPa. Force de maintien (N) ?'], n: 60000 * Math.PI * 0.02 * 0.02, tol: 1, u: 'N', e: ['F = ΔP × π d² / 4 = 60 000 × π × 0.02² ≈ 75 N.', 'F = ΔP × π d² / 4 = 60 000 × π × 0,02² ≈ 75 N.'] },
    { q: ['2 kg part, two fingers, μ = 0.5, safety factor 2. Normal force per finger (N)?', 'Pièce de 2 kg, deux doigts, μ = 0,5, coefficient de sécurité 2. Force normale par doigt (N) ?'], n: 2 * 2 * 9.81 / (2 * 0.5), tol: 0.2, u: 'N', e: ['2 μ N ≥ S m g → N = 2 × 2 × 9.81 / (2 × 0.5) ≈ 39.2 N.', '2 μ N ≥ S m g → N = 2 × 2 × 9,81 / (2 × 0,5) ≈ 39,2 N.'] },
    { q: ['Energy of a 24 V, 10 Ah battery (Wh)?', 'Énergie d\'une batterie de 24 V, 10 Ah (Wh) ?'], n: 240, tol: 0.5, u: 'Wh', e: ['Wh = V × Ah = 24 × 10 = 240 Wh.', 'Wh = V × Ah = 24 × 10 = 240 Wh.'] },
    { q: ['Step of a 10-bit ADC on 5 V (mV)?', 'Pas d\'un convertisseur 10 bits sur 5 V (mV) ?'], n: 5000 / 1024, tol: 0.05, u: 'mV', e: ['U / 2ⁿ = 5 / 1024 ≈ 4.9 mV.', 'U / 2ⁿ = 5 / 1024 ≈ 4,9 mV.'] },
    { q: ['In ROS 2, what is a service?', 'En ROS 2, qu\'est-ce qu\'un service ?'], o: [['A quick question and its answer', 'Une question rapide et sa réponse'], ['A continuous stream of data', 'Un flux continu de données'], ['A long task that can be cancelled', 'Une longue tâche qu\'on peut annuler'], ['A simulator', 'Un simulateur']], a: 0, e: ['Topics stream, services answer, actions follow long tasks.', 'Les topics diffusent, les services répondent, les actions suivent les longues tâches.'] },
    { q: ['Which standard is about collaborative robots (cobots)?', 'Quelle norme concerne les robots collaboratifs (cobots) ?'], o: [['ISO/TS 15066', 'ISO/TS 15066'], ['ISO 9001', 'ISO 9001'], ['ISO 9283', 'ISO 9283'], ['ISO 13855', 'ISO 13855']], a: 0, e: ['ISO 10218 for industrial robots, ISO/TS 15066 for cobots, ISO 13855 for distances.', 'ISO 10218 pour les robots industriels, ISO/TS 15066 pour les cobots, ISO 13855 pour les distances.'] },
    { q: ['Safety distance S = K × T + C with K = 1600 mm/s, T = 0.3 s, C = 100 mm (mm)?', 'Distance de sécurité S = K × T + C avec K = 1600 mm/s, T = 0,3 s, C = 100 mm (mm) ?'], n: 580, tol: 1, u: 'mm', e: ['1600 × 0.3 + 100 = 480 + 100 = 580 mm.', '1600 × 0,3 + 100 = 480 + 100 = 580 mm.'] },
    { q: ['Repeatability versus accuracy: which is usually better on an industrial robot?', 'Répétabilité ou exactitude : laquelle est en général meilleure sur un robot industriel ?'], o: [['Repeatability (coming back to the same point)', 'La répétabilité (revenir au même point)'], ['Accuracy (reaching a point given in numbers)', 'L\'exactitude (atteindre un point donné en chiffres)'], ['They are always equal', 'Elles sont toujours égales'], ['Neither can be measured', 'Aucune ne peut se mesurer']], a: 0, e: ['About 0.02 mm of repeatability against about 1 mm of accuracy, improved by calibration.', 'Environ 0,02 mm de répétabilité contre environ 1 mm d\'exactitude, améliorée par l\'étalonnage.'] },
    { q: ['A cell has a cycle time of 12 s. Parts per hour?', 'Une cellule a un temps de cycle de 12 s. Pièces par heure ?'], n: 300, tol: 0.5, u: '', e: ['3600 / 12 = 300 parts per hour.', '3600 / 12 = 300 pièces par heure.'] },
    { q: ['A cell costs 60 000 € and saves 30 000 € per year. Payback time (years)?', 'Une cellule coûte 60 000 € et économise 30 000 € par an. Retour sur investissement (années) ?'], n: 2, tol: 0.01, u: '', e: ['Cost / savings per year = 60 000 / 30 000 = 2 years.', 'Coût / économies par an = 60 000 / 30 000 = 2 ans.'] }
  ],
  ros: [
    { q: ['What is ROS 2?', 'Qu\'est-ce que ROS 2 ?'], o: [['Middleware that lets the programs of a robot talk, plus tools and libraries', 'Un intergiciel qui fait communiquer les programmes d\'un robot, plus des outils et des bibliothèques'], ['An operating system that replaces Linux', 'Un système d\'exploitation qui remplace Linux'], ['A programming language', 'Un langage de programmation'], ['A robot brand', 'Une marque de robot']], a: 0, e: ['ROS 2 runs on Linux (or others) and connects the nodes of the robot.', 'ROS 2 tourne sur Linux (ou autre) et relie les nœuds du robot.'] },
    { q: ['What is true about a topic?', 'Qu\'est-ce qui est vrai pour un topic ?'], o: [['Nodes publish and subscribe; nobody answers', 'Des nœuds publient et s\'abonnent ; personne ne répond'], ['Only one node may read it', 'Un seul nœud peut le lire'], ['It always answers the sender', 'Il répond toujours à l\'expéditeur'], ['It has no message type', 'Il n\'a pas de type de message']], a: 0, e: ['A topic is a one-way stream with one message type.', 'Un topic est un flux à sens unique avec un seul type de message.'] },
    { q: ['Which units does ROS use?', 'Quelles unités ROS utilise-t-il ?'], o: [['Metres, seconds, radians', 'Mètres, secondes, radians'], ['Millimetres, milliseconds, degrees', 'Millimètres, millisecondes, degrés'], ['Inches and degrees', 'Pouces et degrés'], ['Any unit', 'N\'importe quelle unité']], a: 0, e: ['SI units everywhere (REP 103): angles in radians.', 'Unités SI partout (REP 103) : angles en radians.'] },
    { q: ['Which command shows how often messages arrive on a topic?', 'Quelle commande montre à quelle fréquence les messages arrivent sur un topic ?'], o: [['ros2 topic hz', 'ros2 topic hz'], ['ros2 topic list', 'ros2 topic list'], ['ros2 run', 'ros2 run'], ['colcon build', 'colcon build']], a: 0, e: ['list lists the topics, echo prints the messages, hz measures the rate.', 'list liste les topics, echo affiche les messages, hz mesure la fréquence.'] },
    { q: ['After colcon build, what must you do before ros2 run?', 'Après colcon build, que faut-il faire avant ros2 run ?'], o: [['source install/setup.bash', 'source install/setup.bash'], ['Restart the computer', 'Redémarrer l\'ordinateur'], ['Delete the build folder', 'Supprimer le dossier build'], ['Nothing', 'Rien']], a: 0, e: ['Sourcing makes the new packages visible in this terminal.', 'Le source rend les nouveaux paquets visibles dans ce terminal.'] },
    { q: ['Which interface fits "drive to the kitchen" (long, followed, cancellable)?', 'Quelle interface convient à « aller à la cuisine » (long, suivi, annulable) ?'], o: [['An action', 'Une action'], ['A topic', 'Un topic'], ['A service', 'Un service'], ['A parameter', 'Un paramètre']], a: 0, e: ['Actions give feedback during the task and can be cancelled.', 'Les actions donnent un retour pendant la tâche et peuvent être annulées.'] },
    { q: ['What is a parameter?', 'Qu\'est-ce qu\'un paramètre ?'], o: [['A named setting of a node, that can change while it runs', 'Un réglage nommé d\'un nœud, qui peut changer pendant qu\'il tourne'], ['A message type', 'Un type de message'], ['A topic name', 'Un nom de topic'], ['A launch file', 'Un fichier de lancement']], a: 0, e: ['Parameters let you tune a node without editing its code.', 'Les paramètres permettent de régler un nœud sans modifier son code.'] },
    { q: ['A node uses the topic name "scan" in the namespace robot1. Full name?', 'Un nœud utilise le nom de topic « scan » dans l\'espace de noms robot1. Nom complet ?'], o: [['/robot1/scan', '/robot1/scan'], ['/scan', '/scan'], ['scan/robot1', 'scan/robot1'], ['/robot1', '/robot1']], a: 0, e: ['Names without a leading slash follow the namespace: the same code works for several robots.', 'Les noms sans barre initiale suivent l\'espace de noms : le même code marche pour plusieurs robots.'] },
    { q: ['Usual chain of frames of a mobile robot?', 'Chaîne de repères habituelle d\'un robot mobile ?'], o: [['map → odom → base_link → sensors', 'map → odom → base_link → capteurs'], ['base_link → map → odom', 'base_link → map → odom'], ['odom → map → base_link', 'odom → map → base_link'], ['sensors → map', 'capteurs → map']], a: 0, e: ['The localisation gives map → odom, the odometry odom → base_link, the URDF base_link → sensors.', 'La localisation donne map → odom, l\'odométrie odom → base_link, l\'URDF base_link → capteurs.'] },
    { q: ['Which node turns the URDF and the joint states into tf2 frames?', 'Quel nœud transforme l\'URDF et les états des liaisons en repères tf2 ?'], o: [['robot_state_publisher', 'robot_state_publisher'], ['rviz2', 'rviz2'], ['rosbag', 'rosbag'], ['slam_toolbox', 'slam_toolbox']], a: 0, e: ['It publishes the transforms of all the links described in the URDF.', 'Il publie les transformations de tous les corps décrits dans l\'URDF.'] },
    { q: ['What is rosbag for?', 'À quoi sert rosbag ?'], o: [['To record the topics of a test and replay them later', 'Enregistrer les topics d\'un essai et les rejouer plus tard'], ['To build the packages', 'Compiler les paquets'], ['To draw the robot in 3D', 'Dessiner le robot en 3D'], ['To plan paths', 'Planifier des chemins']], a: 0, e: ['You can debug at your desk with the real data of the robot.', 'On peut déboguer à son bureau avec les vraies données du robot.'] },
    { q: ['Your obstacle-avoidance node stops. What must it do?', 'Votre nœud d\'évitement d\'obstacles s\'arrête. Que doit-il faire ?'], o: [['Send a zero speed on /cmd_vel', 'Envoyer une vitesse nulle sur /cmd_vel'], ['Nothing, the robot stops by itself', 'Rien, le robot s\'arrête tout seul'], ['Delete the map', 'Effacer la carte'], ['Restart ROS 2', 'Redémarrer ROS 2']], a: 0, e: ['Otherwise the last command may keep running; safety (e-stop) stays outside ROS 2.', 'Sinon la dernière commande peut continuer ; la sécurité (arrêt d\'urgence) reste hors de ROS 2.'] }
  ],
  adv: [
    { q: ['For a parallel robot, which model is easy and which is hard?', 'Pour un robot parallèle, quel modèle est facile et lequel est difficile ?'], o: [['Inverse easy (one formula per chain), forward hard', 'Inverse facile (une formule par chaîne), direct difficile'], ['Forward easy, inverse hard', 'Direct facile, inverse difficile'], ['Both easy', 'Les deux faciles'], ['Both impossible', 'Les deux impossibles']], a: 0, e: ['It is the opposite of a serial arm.', 'C\'est l\'inverse d\'un bras série.'] },
    { q: ['Stewart leg: base point (0.5, 0, 0), platform point (0.3, 0, 0), platform at (0, 0, 1) without rotation. Leg length (m)?', 'Jambe de Stewart : point de base (0,5 ; 0 ; 0), point de plateforme (0,3 ; 0 ; 0), plateforme en (0 ; 0 ; 1) sans rotation. Longueur de jambe (m) ?'], n: Math.sqrt(0.04 + 1), tol: 0.005, u: 'm', e: ['ℓ = ‖p + R b − a‖ = ‖(−0.2, 0, 1)‖ = √1.04 ≈ 1.02 m.', 'ℓ = ‖p + R b − a‖ = ‖(−0,2 ; 0 ; 1)‖ = √1,04 ≈ 1,02 m.'] },
    { q: ['In an LQR, what do Q and R mean?', 'Dans une LQR, que veulent dire Q et R ?'], o: [['Q: price of the errors, R: price of the commands', 'Q : prix des erreurs, R : prix des commandes'], ['Q: the robot mass, R: its radius', 'Q : la masse du robot, R : son rayon'], ['Q: the noise, R: the delay', 'Q : le bruit, R : le retard'], ['They are two gains of a PID', 'Ce sont deux gains d\'un PID']], a: 0, e: ['Larger Q → tighter control; larger R → gentler commands.', 'Q plus grand → commande plus serrée ; R plus grand → commandes plus douces.'] },
    { q: ['Bryson\'s rule: the largest acceptable error is 0.1. Weight Q on its diagonal?', 'Règle de Bryson : la plus grande erreur acceptable vaut 0,1. Poids Q sur sa diagonale ?'], n: 100, tol: 0.5, u: '', e: ['Q = 1 / 0.1² = 100.', 'Q = 1 / 0,1² = 100.'] },
    { q: ['What does an MPC do with the sequence of commands it optimises?', 'Que fait une MPC de la suite de commandes qu\'elle optimise ?'], o: [['It applies only the first one, then optimises again', 'Elle n\'applique que la première, puis optimise à nouveau'], ['It applies all of them without measuring', 'Elle les applique toutes sans mesurer'], ['It applies the last one', 'Elle applique la dernière'], ['It sends them to the user', 'Elle les envoie à l\'utilisateur']], a: 0, e: ['Replanning at every sample closes the loop with the newest measurement.', 'Replanifier à chaque échantillon ferme la boucle avec la mesure la plus récente.'] },
    { q: ['Linear inverted pendulum with z_c = 0.981 m. ω = √(g / z_c) in rad/s?', 'Pendule inversé linéaire avec z_c = 0,981 m. ω = √(g / z_c) en rad/s ?'], n: Math.sqrt(10), tol: 0.01, u: 'rad/s', e: ['√(9.81 / 0.981) = √10 ≈ 3.16 rad/s.', '√(9,81 / 0,981) = √10 ≈ 3,16 rad/s.'] },
    { q: ['Capture point ξ = x + ẋ / ω with x = 0, ẋ = 0.5 m/s, ω = 2.5 rad/s (m)?', 'Point de capture ξ = x + ẋ / ω avec x = 0, ẋ = 0,5 m/s, ω = 2,5 rad/s (m) ?'], n: 0.2, tol: 0.005, u: 'm', e: ['0 + 0.5 / 2.5 = 0.2 m: put the foot there to stop.', '0 + 0,5 / 2,5 = 0,2 m : posez le pied là pour s\'arrêter.'] },
    { q: ['A 2 kg quadrotor hovers. Thrust of each of its 4 motors (N)?', 'Un quadrirotor de 2 kg fait du vol stationnaire. Poussée de chacun de ses 4 moteurs (N) ?'], n: 2 * 9.81 / 4, tol: 0.02, u: 'N', e: ['Total thrust m g = 19.62 N, shared by 4: 4.9 N each.', 'Poussée totale m g = 19,62 N, partagée par 4 : 4,9 N chacun.'] },
    { q: ['A quadrotor tilts by 10° at constant altitude. Horizontal acceleration (m/s²)?', 'Un quadrirotor s\'incline de 10° à altitude constante. Accélération horizontale (m/s²) ?'], n: 9.81 * Math.tan(10 * Math.PI / 180), tol: 0.02, u: 'm/s²', e: ['a = g tan φ = 9.81 × tan 10° ≈ 1.73 m/s².', 'a = g tan φ = 9,81 × tan 10° ≈ 1,73 m/s².'] },
    { q: ['Depth camera: u = 420 px, cₓ = 320 px, Z = 1 m, f = 500 px. X of the point (m)?', 'Caméra de profondeur : u = 420 px, cₓ = 320 px, Z = 1 m, f = 500 px. X du point (m) ?'], n: 0.2, tol: 0.005, u: 'm', e: ['X = (u − cₓ) Z / f = 100 × 1 / 500 = 0.2 m.', 'X = (u − cₓ) Z / f = 100 × 1 / 500 = 0,2 m.'] },
    { q: ['Q-learning: Q = 2, r = 1, max Q′ = 5, γ = 0.9, α = 0.1. New Q?', 'Q-learning : Q = 2, r = 1, max Q′ = 5, γ = 0,9, α = 0,1. Nouveau Q ?'], n: 2.35, tol: 0.005, u: '', e: ['Target 1 + 0.9 × 5 = 5.5; error 3.5; Q = 2 + 0.1 × 3.5 = 2.35.', 'Cible 1 + 0,9 × 5 = 5,5 ; erreur 3,5 ; Q = 2 + 0,1 × 3,5 = 2,35.'] },
    { q: ['Gripper: 1 kg part, two 90° V-jaws, μ = 0.2, a = 0, S = 2. Normal force per jaw (N)?', 'Pince : pièce de 1 kg, deux mors en V à 90°, μ = 0,2, a = 0, S = 2. Force normale par mors (N) ?'], n: 2 * 9.81 / (2 * 0.2 / Math.sin(Math.PI / 4)), tol: 0.3, u: 'N', e: ['μ_eff = 0.2 / sin 45° ≈ 0.283; N = 2 × 1 × 9.81 / (2 × 0.283) ≈ 34.7 N.', 'μ_eff = 0,2 / sin 45° ≈ 0,283 ; N = 2 × 1 × 9,81 / (2 × 0,283) ≈ 34,7 N.'] }
  ],
  wmr: [
    { q: ['Convert 60 rpm into rad/s.', 'Convertissez 60 tr/min en rad/s.'], n: 2 * Math.PI, tol: 0.01, u: 'rad/s', e: ['rpm × 2π / 60 = 60 × 2π / 60 = 2π ≈ 6.28 rad/s.', 'tr/min × 2π / 60 = 60 × 2π / 60 = 2π ≈ 6,28 rad/s.'] },
    { q: ['What is the main weakness of odometry?', 'Quelle est la principale faiblesse de l\'odométrie ?'], o: [['It drifts: the error grows with the distance', 'Elle dérive : l\'erreur grandit avec la distance'], ['It is too slow', 'Elle est trop lente'], ['It needs a camera', 'Elle a besoin d\'une caméra'], ['It only works outdoors', 'Elle ne marche qu\'en extérieur']], a: 0, e: ['Small errors of radius, track and slip add up.', 'Les petites erreurs de rayon, de voie et de glissement s\'additionnent.'] },
    { q: ['How many numbers describe the pose of a robot on the floor?', 'Combien de nombres décrivent la pose d\'un robot sur le sol ?'], n: 3, tol: 0.01, u: '', e: ['ξ = (x, y, θ): two for the position, one for the heading.', 'ξ = (x, y, θ) : deux pour la position, un pour le cap.'] },
    { q: ['Which wheels impose a sliding constraint (no speed across the wheel plane)?', 'Quelles roues imposent une contrainte de glissement (pas de vitesse en travers du plan de la roue) ?'], o: [['Fixed and steered standard wheels', 'Les roues standard fixes et orientables'], ['Castor wheels', 'Les roues folles'], ['Swedish (Mecanum) wheels', 'Les roues suédoises (Mecanum)'], ['Spherical wheels', 'Les roues sphériques']], a: 0, e: ['Castor, Swedish and spherical wheels can move across their plane.', 'Les roues folles, suédoises et sphériques peuvent bouger en travers de leur plan.'] },
    { q: ['Differential robot: V_R = 0.6 m/s, V_L = 0.4 m/s. Linear speed v (m/s)?', 'Robot différentiel : V_R = 0,6 m/s, V_L = 0,4 m/s. Vitesse linéaire v (m/s) ?'], n: 0.5, tol: 0.005, u: 'm/s', e: ['v = (V_R + V_L) / 2 = 0.5 m/s.', 'v = (V_R + V_L) / 2 = 0,5 m/s.'] },
    { q: ['Same robot with a track L = 0.4 m. Angular speed ω (rad/s)?', 'Même robot avec une voie L = 0,4 m. Vitesse angulaire ω (rad/s) ?'], n: 0.5, tol: 0.005, u: 'rad/s', e: ['ω = (V_R − V_L) / L = 0.2 / 0.4 = 0.5 rad/s.', 'ω = (V_R − V_L) / L = 0,2 / 0,4 = 0,5 rad/s.'] },
    { q: ['Same robot: turning radius R = v / ω (m)?', 'Même robot : rayon de virage R = v / ω (m) ?'], n: 1, tol: 0.01, u: 'm', e: ['R = 0.5 / 0.5 = 1 m.', 'R = 0,5 / 0,5 = 1 m.'] },
    { q: ['Wanted v = 1 m/s and ω = 1 rad/s, track L = 0.5 m. Right wheel speed V_R (m/s)?', 'On veut v = 1 m/s et ω = 1 rad/s, voie L = 0,5 m. Vitesse de la roue droite V_R (m/s) ?'], n: 1.25, tol: 0.005, u: 'm/s', e: ['V_R = v + ω L / 2 = 1 + 0.25 = 1.25 m/s.', 'V_R = v + ω L / 2 = 1 + 0,25 = 1,25 m/s.'] },
    { q: ['Bicycle model: v = 2 m/s, wheelbase ℓ = 1 m, steering δ = 0.2 rad. ω (rad/s)?', 'Modèle bicyclette : v = 2 m/s, empattement ℓ = 1 m, braquage δ = 0,2 rad. ω (rad/s) ?'], n: 2 * Math.tan(0.2), tol: 0.005, u: 'rad/s', e: ['ω = v tan δ / ℓ = 2 × tan 0.2 ≈ 0.405 rad/s.', 'ω = v tan δ / ℓ = 2 × tan 0,2 ≈ 0,405 rad/s.'] },
    { q: ['Ackermann steering: which front wheel turns more?', 'Direction d\'Ackermann : quelle roue avant braque le plus ?'], o: [['The inside wheel', 'La roue intérieure'], ['The outside wheel', 'La roue extérieure'], ['Both turn the same', 'Les deux braquent pareil'], ['The rear wheels', 'Les roues arrière']], a: 0, e: ['So that all the wheel axes meet at the ICR on the rear axle.', 'Pour que tous les axes de roues se coupent au CIR sur l\'essieu arrière.'] },
    { q: ['Degree of maneuverability δM of a car-like robot?', 'Degré de manœuvrabilité δM d\'un robot de type voiture ?'], n: 2, tol: 0.01, u: '', e: ['δm = 1, δs = 1, δM = δm + δs = 2.', 'δm = 1, δs = 1, δM = δm + δs = 2.'] },
    { q: ['What is the difference between a path and a trajectory?', 'Quelle est la différence entre un chemin et une trajectoire ?'], o: [['A trajectory is a path with the time', 'Une trajectoire est un chemin avec le temps'], ['None', 'Aucune'], ['A path is always straight', 'Un chemin est toujours droit'], ['A trajectory has no heading', 'Une trajectoire n\'a pas de cap']], a: 0, e: ['The path is the curve in (x, y, θ); the trajectory says when each point is reached.', 'Le chemin est la courbe dans (x, y, θ) ; la trajectoire dit quand chaque point est atteint.'] }
  ]
};
